import type { Option } from "effect";
import type { Command } from "foldkit";
import * as Ui from "@foldkit/ui";

export const { Model } = Ui.Tooltip;
export type Model = Ui.Tooltip.Model;

export const {
  AnchorTooltip,
  BlurredTrigger,
  CompletedAnchorTooltip,
  ElapsedShowDelay,
  EnteredTrigger,
  FocusedTrigger,
  Hidden,
  LeftTrigger,
  Message,
  OutMessage,
  PressedEscape,
  PressedPointerOnTrigger,
  ShowAfterDelay,
  Shown,
  reflectShowDelay,
  update,
  view,
} = Ui.Tooltip;

export type BlurredTrigger = Ui.Tooltip.BlurredTrigger;
export type EnteredTrigger = Ui.Tooltip.EnteredTrigger;
export type FocusedTrigger = Ui.Tooltip.FocusedTrigger;
export type Hidden = Ui.Tooltip.Hidden;
export type InitConfig = Ui.Tooltip.InitConfig;
export type LeftTrigger = Ui.Tooltip.LeftTrigger;
export type Message = Ui.Tooltip.Message;
export type OutMessage = Ui.Tooltip.OutMessage;
export type PressedEscape = Ui.Tooltip.PressedEscape;
export type PressedPointerOnTrigger = Ui.Tooltip.PressedPointerOnTrigger;
export type RenderInfo = Ui.Tooltip.RenderInfo;
export type Shown = Ui.Tooltip.Shown;
export type ViewInputs = Ui.Tooltip.ViewInputs;
export type InitReturn = readonly [Model, readonly Command.Command<Message>[]];
export type UpdateReturn = readonly [
  Model,
  readonly Command.Command<Message>[],
  Option.Option<OutMessage>,
];

export const init = (config: InitConfig): InitReturn => [
  Ui.Tooltip.init(config),
  [],
];

export {
  panelClasses,
  tooltipAnchor,
  tooltipRootClasses,
  tooltipTriggerClasses,
  tooltipView,
} from "./view";
export type { TooltipViewInput } from "./view";

import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import type { AnchorConfig } from "@foldkit/ui/tooltip";

import type { RenderInfo } from "./index";

export const tooltipTriggerClasses =
  "inline-flex cursor-pointer select-none items-center gap-1.5 rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-900 transition hover:bg-gray-100 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const panelClasses =
  "rounded-md bg-gray-900 px-3 py-1.5 text-sm text-white shadow-lg";

export const tooltipRootClasses = "relative inline-block";

export const tooltipAnchor: AnchorConfig = {
  placement: "top",
  gap: 6,
  padding: 8,
};

export type TooltipViewInput = Readonly<{
  render: RenderInfo;
  triggerLabel: string;
  panelText: string;
}>;

export const tooltipView = ({
  render,
  triggerLabel,
  panelText,
}: TooltipViewInput): Html => {
  const h = html();

  return h.div(
    [h.Class(tooltipRootClasses)],
    [
      h.button(
        [...render.trigger, h.Class(tooltipTriggerClasses)],
        [h.span([], [triggerLabel])]
      ),
      render.isVisible
        ? h.div(
            [...render.panel, h.Class(panelClasses)],
            [h.span([], [panelText])]
          )
        : h.empty,
    ]
  );
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Tooltip from "./index";

const tooltipId = "registry-tooltip";
const GotTooltipMessage = m("GotTooltipMessage", {
  message: Tooltip.Message,
});
const Model = S.Struct({ tooltip: Tooltip.Model, status: S.String });
type Model = typeof Model.Type;
const Message = S.Union([GotTooltipMessage]);
type Message = typeof Message.Type;

const [tooltip] = Tooltip.init({ id: tooltipId, showDelay: 0 });
const initialModel: Model = {
  tooltip,
  status: "Tooltip hidden.",
};

const toParentMessage = (message: Tooltip.Message): Message =>
  GotTooltipMessage({ message });

const AnchorTooltip = Tooltip.AnchorTooltip({
  buttonId: `${tooltipId}-trigger`,
  anchor: Tooltip.tooltipAnchor,
});

const resolveTooltipMount = () =>
  Scene.Mount.resolve(
    AnchorTooltip,
    Tooltip.CompletedAnchorTooltip(),
    toParentMessage
  );

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotTooltipMessage: ({ message }) => {
        const [tooltip, commands, maybeOutMessage] = Tooltip.update(
          model.tooltip,
          message
        );
        const status = Option.match(maybeOutMessage, {
          onNone: () => model.status,
          onSome: M.type<Tooltip.OutMessage>().pipe(
            M.tagsExhaustive({
              Hidden: () => "Tooltip hidden.",
              Shown: () => "Tooltip shown.",
            })
          ),
        });

        return [
          evo(model, { tooltip: () => tooltip, status: () => status }),
          Command.mapMessages(commands, toParentMessage),
        ];
      },
    })
  );

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.tooltip.id,
        model: model.tooltip,
        view: Tooltip.view,
        viewInputs: {
          anchor: Tooltip.tooltipAnchor,
          toView: (render) =>
            Tooltip.tooltipView({
              render,
              triggerLabel: "Hover details",
              panelText: "Helpful details",
            }),
        },
        toParentMessage,
      }),
      h.p([], [model.status]),
    ]
  );
});

describe("Tooltip registry view", () => {
  test("shows after hover delay and resolves panel mount", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("button", { name: "Hover details" })).toHaveAttr(
        "aria-describedby",
        `${tooltipId}-panel`
      ),
      Scene.expect(Scene.text("Helpful details")).not.toExist(),
      Scene.hover(Scene.role("button", { name: "Hover details" })),
      Scene.Command.resolve(
        Tooltip.ShowAfterDelay({
          delay: initialModel.tooltip.showDelay,
          version: 1,
        }),
        Tooltip.ElapsedShowDelay({ version: 1 }),
        toParentMessage
      ),
      resolveTooltipMount(),
      Scene.expect(Scene.role("tooltip")).toExist(),
      Scene.expect(Scene.text("Helpful details")).toExist(),
      Scene.expect(Scene.text("Tooltip shown.")).toExist()
    );
  });

  test("opens on keyboard focus and hides on blur", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.focus(Scene.role("button", { name: "Hover details" })),
      resolveTooltipMount(),
      Scene.expect(Scene.text("Helpful details")).toExist(),
      Scene.expect(Scene.text("Tooltip shown.")).toExist(),
      Scene.blur(Scene.role("button", { name: "Hover details" })),
      Scene.Mount.expectEnded(AnchorTooltip),
      Scene.expect(Scene.text("Helpful details")).not.toExist(),
      Scene.expect(Scene.text("Tooltip hidden.")).toExist()
    );
  });
});
